def btn(href,label,cls='btn-primary',external=False,download=False):
    return f'<a class="btn {cls}" href="{e(href,quote=True)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+(' download' if download else '')+f'>{e(label)}{EXTERNAL if external else ARROW}</a>'

def a_link(href,label,external=False):
    return f'<a class="text-link" href="{e(href,quote=True)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{e(label)}{EXTERNAL if external else ARROW}</a>'

def tags(items): return '<div class="pill-row">'+''.join(f'<span class="tag">{e(x)}</span>' for x in items)+'</div>'

def head(title,description,path):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#0b241f"><title>{e(title)} | Praveen Khatri</title><meta name="description" content="{e(description,quote=True)}"><meta name="author" content="Praveen Khatri"><meta property="og:type" content="website"><meta property="og:title" content="{e(title,quote=True)} | Praveen Khatri"><meta property="og:description" content="{e(description,quote=True)}"><link rel="icon" type="image/png" sizes="192x192" href="assets/images/favicon.png"><link rel="apple-touch-icon" sizes="180x180" href="assets/images/apple-touch-icon.png"><link rel="stylesheet" href="assets/css/style.css"><script src="assets/js/main.js" defer></script></head><body><a class="skip-link" href="#main">Skip to main content</a>{header(path)}'''

def header(active):
    pages=[('index.html','Home'),('research.html','Research'),('publications.html','Publications'),('about.html','About'),('cv.html','CV')]
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==active else '')+f'>{name}</a>' for url,name in pages)
    return f'''<header class="site-header"><div class="shell nav-inner"><a class="brand" href="index.html" aria-label="Praveen Khatri, home"><span class="brand-mark" aria-hidden="true">P.</span><span class="brand-text">Praveen Khatri<span>Plant molecular biologist</span></span></a><nav class="site-nav" id="primary-navigation" aria-label="Main navigation">{nav}<a href="contact.html" {'aria-current="page"' if active=='contact.html' else ''}>Contact</a></nav><div class="nav-actions"><a class="btn btn-dark nav-cta" href="contact.html">Get in touch{ARROW}</a><button class="menu-toggle" type="button" data-menu-toggle aria-expanded="false" aria-controls="primary-navigation" aria-label="Toggle navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div></div></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="shell"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">P.</span><span class="brand-text">Praveen Khatri<span>Plant molecular biologist</span></span></a><p>Exploring the enzymes, genes and chemistry behind the remarkable diversity of plant natural products.</p></div><div><div class="footer-title">Explore</div><div class="footer-links"><a href="research.html">Research</a><a href="publications.html">Publications</a><a href="about.html">About</a><a href="cv.html">Curriculum vitae</a><a href="contact.html">Contact</a></div></div><div><div class="footer-title">Elsewhere</div><div class="footer-links"><a href="{ORCID}" target="_blank" rel="noopener noreferrer">ORCID</a><a href="{SCHOLAR}" target="_blank" rel="noopener noreferrer">Google Scholar</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn</a><a href="mailto:{EMAIL}">Email</a></div></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Praveen Khatri. Built with care for scientific curiosity.</span><span>Static HTML · No analytics · GitHub Pages-ready</span></div></div></footer></body></html>'''

def pagehero(crumb,title,sub,links=''):
    return f'''<section class="page-hero"><div class="shell"><div class="bread"><a href="index.html">Home</a><span>/</span>{e(crumb)}</div><span class="eyebrow light">{e(crumb)}</span><h1>{title}</h1><p>{sub}</p>{links}</div></section>'''

def cta():return f'''<section class="cta-band"><div class="shell cta-inner"><div><span class="eyebrow">Connect & collaborate</span><h2>Curiosity works better together.</h2><p>Interested in natural-product biosynthesis, biochemical discovery or collaborative research? I would be glad to hear from you.</p></div>{btn('contact.html','Start a conversation','btn-dark')}</div></section>'''

def projectcard(p):
    return f'''<article class="research-card"><img src="assets/images/{p['image']}" alt="Conceptual illustration: {e(p['name'],quote=True)}" width="920" height="650"><div class="research-card-body"><span class="eyebrow">{e(p['num'])}</span><h3>{e(p['name'])}</h3><p>{e(p['summary'])}</p>{a_link('research.html','Explore the research')}</div></article>'''

