    html+='''<section class="section honors-section"><div class="shell"><div class="section-header"><div><span class="eyebrow">Recognition</span><h2>Research, leadership<br>&amp; <span class="serif-italic">community.</span></h2></div></div><div class="award-highlight"><article class="award-card"><span class="year">2026 · RESEARCH</span><h3>Postdoctoral Competitive Research Award</h3><p>University of Toronto · CAD 30,000 independent research support.</p></article><article class="award-card"><span class="year">2026 · SOCIETY SERVICE</span><h3>Exceptional Young Member Contribution Award</h3><p>Phytochemical Society of North America.</p></article><article class="award-card"><span class="year">2026 · LEADERSHIP</span><h3>Postdoctoral Leadership Recognition Prize</h3><p>University of Toronto Mississauga.</p></article></div><div style="margin-top:28px">'''+a_link('about.html#awards','More awards & recognition')+'''</div></div></section>'''
