def research():
    html=head('Research','Projects in salvinorin A biosynthesis, soybean glyceollin and isoflavone hydroxylase biology, P450 enzyme discovery and time-course transcriptomics.','research.html')
    html+='<main id="main">'+pagehero('Research','From molecular diversity<br>to <em class="serif-italic" style="color:var(--lime)">biological function.</em>','My research investigates how plant enzymes create specialized molecules and how those molecules contribute to defense, adaptation and chemical innovation.','<div class="subnav"><a href="#projects">Research programs</a><a href="#toolkit">Experimental toolkit</a></div>')
    html+='<section class="section" id="projects"><div class="shell"><div class="section-header"><div><span class="eyebrow">Research portfolio</span><h2>Questions worth<br><span class="serif-italic">investigating.</span></h2></div></div>'
    for i,p in enumerate(PROJECTS):
        html+=f'''<article class="project-panel {'reverse' if i%2 else ''}"><div class="project-text"><span class="caps">{e(p['num'])} · {e(p['status'])}</span><h2>{e(p['name'])}</h2><p class="lead">{e(p['summary'])}</p><p>{e(p['desc'])}</p><h4>Research question</h4><p>{e(p['question'])}</p>{tags(p['methods'])}'''
        if p['link']:html+=a_link(p['link'],'Read the related work',external=True)
        html+='</div><div class="project-image"><img src="assets/images/'+p['image']+'" alt="Conceptual scientific artwork illustrating '+e(p['name'],quote=True)+'" width="920" height="650"></div></article>'
    html+='</div></section>'
    html+='''<section class="section honors-section" id="toolkit"><div class="shell"><span class="eyebrow">Technical toolkit</span><h2 style="margin:14px 0 37px">Integrated methods.<br><span class="serif-italic">Stronger evidence.</span></h2><div class="skill-groups"><div class="skill-group"><h4>Molecular &amp; enzymatic biology</h4><p>Gene cloning, yeast expression, protein assays, functional characterization of cytochrome P450s, RT-qPCR, plant transformation systems.</p></div><div class="skill-group"><h4>Analytical chemistry</h4><p>HPLC, LC–MS, GC–MS, NMR-informed metabolite identification, targeted profiling and chromatographic method development.</p></div><div class="skill-group"><h4>Computational biology</h4><p>RNA-seq, pathway enrichment, co-expression networks, comparative genomics, phylogenetics and candidate prioritization.</p></div><div class="skill-group"><h4>Metabolic pathway discovery</h4><p>Substrate screening, biosynthetic reconstruction, genotype-to-chemistry interpretation and heterologous validation.</p></div></div></div></section>'''+cta()+'</main>'+footer();return html

